import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
  locale?: string;
}

const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => {
  const base = startOfDay(new Date());
  base.setDate(base.getDate() + days);
  return base;
};

const presets = [
  { key: 'today', label: 'Сегодня', offset: 0 },
  { key: 'yesterday', label: 'Вчера', offset: -1 },
  { key: 'week', label: 'Неделя назад', offset: -7 },
];

const isSameDay = (a: Date | null | undefined, b: Date) =>
  !!a && startOfDay(a).getTime() === b.getTime();

export default function ReportDatePicker({
  value,
  defaultValue = null,
  onChange,
  locale = 'ru-RU',
}: ReportDatePickerProps) {
  const [internal, setInternal] = useState<Date | null>(defaultValue);
  const selected = value !== undefined ? value : internal;

  const select = (next: Date | null) => {
    if (value === undefined) setInternal(next);
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12, maxWidth: 320 }}>
      <div role="group" aria-label="Быстрый выбор даты" style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
        {presets.map((preset) => {
          const date = shiftDays(preset.offset);
          const active = isSameDay(selected, date);
          return (
            <JxChip
              key={preset.key}
              role="button"
              tabIndex={0}
              aria-pressed={active}
              active={active}
              onClick={() => select(date)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  select(date);
                }
              }}
            >
              {preset.label}
            </JxChip>
          );
        })}
      </div>

      <JxCalendar
        locale={locale}
        value={selected}
        onValueChange={select}
        aria-label="Дата отчёта"
      />

      <p style={{ margin: 0, color: 'var(--jx-text-2)', fontFamily: 'var(--jx-font-sans)' }}>
        {selected
          ? `Отчёт за ${selected.toLocaleDateString(locale, { day: 'numeric', month: 'long', year: 'numeric' })}`
          : 'Дата не выбрана — выберите день в календаре или быстрый вариант выше.'}
      </p>
    </div>
  );
}

